def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If no opponents are alive, we can bid minimally but still meet requirement if possible.
    if not alive_opponents:
        target = min(my_budget, DAILY_SALARY * 0.25)
        return max(0.0, float(target))

    # Reaction to yesterday's bidding pressure (only immediate previous_trace).
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Baseline bid: try to be competitive enough to secure water when supply is near/above WATER_REQ.
    # Supply normalization: 15->0, 25->1
    denom = float(MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0.0:
        supply_factor = 0.5
    else:
        supply_factor = (supply - float(MIN_SUPPLY)) / denom
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # If we are under pressure, increase bid.
    hp_pressure = 0.0
    if my_hp <= 2:
        hp_pressure = 1.0
    elif my_hp <= 4:
        hp_pressure = 0.6
    elif my_hp <= 6:
        hp_pressure = 0.3

    no_water_pressure = 0.0
    if my_no_water_days >= 3:
        no_water_pressure = 1.0
    elif my_no_water_days == 2:
        no_water_pressure = 0.6
    elif my_no_water_days == 1:
        no_water_pressure = 0.25

    # Base competitiveness: higher when supply is low relative to requirement.
    # If supply is 15-25 and our need is 13, we still may face scarcity if others bid.
    scarcity = 1.0 - supply_factor

    # Default target bid in budget terms.
    # Keep it moderate unless our state is critical.
    base_multiplier = 0.45 + 0.25 * scarcity
    base_multiplier += 0.25 * hp_pressure + 0.20 * no_water_pressure

    # Adjust based on yesterday's max bid if available.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If opponents were bidding near our daily salary, match/beat slightly.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            base_multiplier = 0.75 + 0.25 * hp_pressure
        elif highest_prev_bid >= DAILY_SALARY * 0.60:
            base_multiplier = max(base_multiplier, 0.55 + 0.20 * scarcity)
        else:
            # If they were bidding low, we can bid closer to baseline.
            base_multiplier = max(base_multiplier, 0.40 + 0.20 * scarcity)

    # Convert multiplier to bid, cap by budget.
    bid = my_budget
    desired = DAILY_SALARY * base_multiplier
    if desired < 0.0:
        desired = 0.0

    # If our budget is very low, still bid as much as possible to avoid death.
    bid = min(my_budget, desired)

    # Ensure some minimum activity when we are in danger.
    if hp_pressure >= 0.6 or no_water_pressure >= 0.6:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.65))

    # If day is late in episode, slightly increase urgency.
    if day >= 7:
        bid = min(my_budget, bid + DAILY_SALARY * 0.10)

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive_opponents = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_opponents += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return min(budget, 55)
        return min(budget, 18)

    total_players = 1 + len(alive_opponents)
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < total_players
    very_scarce = expected_units < max(1.0, total_players - 0.5)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2
    if scarcity:
        danger += 1
    if very_scarce:
        danger += 1
    if urgent_opponents >= len(alive_opponents) / 2.0:
        danger += 1

    if danger >= 6:
        target = max(78, highest_prev + 3)
    elif danger >= 4:
        target = max(62, highest_prev + 2)
    elif danger >= 2:
        if highest_prev >= 75:
            target = 38
        else:
            target = max(42, avg_prev + 1.5)
    else:
        if highest_prev >= 80:
            target = 22
        elif scarcity:
            target = max(34, avg_prev)
        else:
            target = 16

    if rich_opponents >= 2 and scarcity:
        target += 4
    if budget < DAILY_SALARY:
        target = min(target, budget * 0.7)
    elif budget < DAILY_SALARY * 2:
        target = min(target, budget * 0.85)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, 82)

    bid = min(budget, max(0, target))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Determine alive opponents
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        # No competition, bid minimal to save money
        return min(budget, DAILY_SALARY * 0.2)

    # Collect yesterday's bids from alive opponents
    prev_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # Base bid: enough to secure water if supply is low
    base_bid = DAILY_SALARY * 0.3

    # Adjust based on my health and number of days without water
    if hp <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)
    if no_water_days >= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)

    # Adjust based on opponent's previous bids
    if prev_bids:
        max_prev = max(prev_bids)
        mean_prev = sum(prev_bids) / len(prev_bids)
        # If opponents bid high, they may be desperate; outbid moderately
        if max_prev >= DAILY_SALARY * 0.7:
            # They are aggressive; match or slightly beat if we have budget
            target = max_prev + 5
            if budget >= target:
                base_bid = max(base_bid, target)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.5)
        elif mean_prev > DAILY_SALARY * 0.4:
            # Moderate pressure, bid slightly above mean
            base_bid = max(base_bid, mean_prev + 3)
        else:
            # Opponents are cautious, we can be conservative
            base_bid = max(base_bid, DAILY_SALARY * 0.25)

    # Ensure we don't exceed budget
    bid = min(budget, base_bid)
    # Also ensure we don't bid more than needed to secure water (supply might be small)
    max_effective = DAILY_SALARY * 0.9
    bid = min(bid, max_effective)
    return int(bid)
